package com.ruoyi.medical.persistence;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import org.springframework.mock.web.*;import com.ruoyi.medical.identity.*;import com.ruoyi.medical.contracts.*;import com.fasterxml.jackson.databind.JsonNode;import java.util.*;import java.time.*;
/** Actual controller/schema transport gates; business private proof provenance is tested by its authority suites. */
class FormalInvocationControllerTest {
 FormalInvocationController controller;FormalInvocationService service;ServiceCertificateIdentity identity;FormalInvocationSchema schema;MockHttpServletRequest request;MockHttpServletResponse response;JsonNode action;
 @BeforeEach void setup()throws Exception{schema=new FormalInvocationSchema();service=mock(FormalInvocationService.class);identity=mock(ServiceCertificateIdentity.class);controller=new FormalInvocationController(identity,service,new FormalInvocationHttpSchema(schema),schema);request=new MockHttpServletRequest();request.addHeader("X-Schema-Version","1.0.0");request.addHeader("X-Run-Token","actual-token-boundary-fixture");response=new MockHttpServletResponse();action=schema.parse("{\"run_id\":\""+id(1)+"\",\"step_id\":\""+id(2)+"\",\"action_id\":\""+id(3)+"\",\"lease_generation\":\"1\",\"input_sha256\":\""+"a".repeat(64)+"\",\"arguments_sha256\":\""+"b".repeat(64)+"\",\"kind\":\"MODEL_CALL\",\"tool_version\":\"formal-fixed\",\"scope\":{\"tenant_id\":\""+id(4)+"\",\"project_id\":\""+id(5)+"\",\"resource_kind\":\"CONFIGURATION\",\"resource_id\":\""+id(6)+"\"},\"action\":\"model.send\",\"purpose\":\"MODEL_VERIFICATION\"}");var b=new com.fasterxml.jackson.databind.ObjectMapper().createObjectNode().put("schema_version","1.0.0").put("expected_dispatch_generation","0");b.set("worker_action",action);request.setContent(ContentReadAuthorization.canonicalBytes(b));}
 @Test void unauthenticatedCallerCannotReadAnyBody()throws Exception{var http=spy(request);doThrow(new TenantAccessException(ErrorCode.ACCESS_DENIED)).when(identity).require(http);assertThrows(TenantAccessException.class,()->controller.begin(http,response,id(8)));verify(http,never()).getInputStream();verifyNoInteractions(service);}
 @Test void duplicateTokenHeaderCannotReachBusiness()throws Exception{request.addHeader("X-Run-Token","second");assertThrows(TenantAccessException.class,()->controller.begin(request,response,id(8)));verifyNoInteractions(service);}
 @Test void duplicateSchemaHeaderCannotReachBusiness()throws Exception{request.addHeader("X-Schema-Version","1.0.0");assertThrows(TenantAccessException.class,()->controller.begin(request,response,id(8)));verifyNoInteractions(service);}
 @Test void repeatedSendHasNoBodyOrCredentialReferences()throws Exception{when(service.beginDispatch(eq(request),anyString(),any(),eq(id(8)))).thenReturn(Optional.empty());var data=controller.begin(request,response,id(8)).required("data");assertFalse(data.required("new_send_admission").booleanValue());assertTrue(data.required("provider_body").isNull());assertTrue(data.required("credential_reference_id").isNull());assertEquals("no-store",response.getHeader("Cache-Control"));}
 @Test void firstAdmissionConsumesActualPrivatePermitOnce()throws Exception{var p=mock(FormalInvocationDispatch.Permit.class);when(p.claimProviderBody()).thenReturn(schema.parse("{\"model\":\"deepseek-chat\"}"));when(p.deadline()).thenReturn(LocalDateTime.of(2026,10,18,20,0));when(p.attemptId()).thenReturn(id(9));when(p.serviceUri()).thenReturn("spiffe://fixture/gateway");when(p.credentialReferenceId()).thenReturn(id(10));when(p.credentialRevision()).thenReturn("fixed");when(p.canonicalProviderBodySha256()).thenReturn("c".repeat(64));when(service.beginDispatch(eq(request),anyString(),any(),eq(id(8)))).thenReturn(Optional.of(p));var data=controller.begin(request,response,id(8)).required("data");assertTrue(data.required("new_send_admission").booleanValue());assertEquals("deepseek-chat",data.required("provider_body").required("model").textValue());verify(p,times(1)).claimProviderBody();}
 @Test void WrongGenerationRejectedBeforeBusiness()throws Exception{request.setContent(new String(request.getContentAsByteArray(),java.nio.charset.StandardCharsets.UTF_8).replace("\"expected_dispatch_generation\":\"0\"","\"expected_dispatch_generation\":\"1\"").getBytes(java.nio.charset.StandardCharsets.UTF_8));assertThrows(TenantAccessException.class,()->controller.begin(request,response,id(8)));verifyNoInteractions(service);}
 static String id(int n){return "00000000-0000-4000-8000-"+String.format("%012d",n);}
}
